function activity(PDO $pdo,$t,$b,$u,$event,$id,$title,$details){try{$q=$pdo->prepare("INSERT INTO activity_events(tenant_id,branch_id,actor_user_id,actor_type,event_type,related_type,related_id,client_id,title,details_json,visible_to_client) VALUES(:t,:b,:u,'user',:e,'client',:r,:c,:title,:d,0)");$q->execute(array(':t'=>$t,':b'=>$b>0?$b:null,':u'=>$u,':e'=>substr($event,0,120),':r'=>$id,':c'=>$id,':title'=>substr($title,0,255),':d'=>cj($details)));}catch(Throwable $e){error_log('client activity: '.$e->getMessage());}}
